// API client for ITD Hackathon backend integration
const API_BASE = 'https://virtserver.swaggerhub.com/itdglobal/itd-hackathon-2025/1';

// API Types based on OpenAPI specification
export interface QuoteRequest {
  weight: number;
  length: number;
  width: number;
  height: number;
  senderPostcode: string;
  receiverPostcode: string;
  serviceSpeed: string;
}

export interface QuoteResponse {
  price: number;
  currency: string;
}

export interface TrackingResponse {
  expected: string; // ISO datetime
  history: Array<{
    status: string;
    time: string; // ISO datetime
  }>;
}

// Quote API Client
export async function getQuote(data: QuoteRequest): Promise<QuoteResponse> {
  try {
    const response = await fetch(`${API_BASE}/quote`, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data)
    });
    
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.message || `Quote API error: ${response.status}`);
    }
    
    return await response.json();
  } catch (error) {
    console.error('Quote API error:', error);
    throw error;
  }
}

// Tracking API Client
export async function getTracking(trackingId: string): Promise<TrackingResponse> {
  try {
    const response = await fetch(`${API_BASE}/parcel`, {
      method: 'POST', 
      headers: { 
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ trackingId })
    });
    
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      if (response.status === 404) {
        throw new Error('Tracking number not found. Please check and try again.');
      }
      throw new Error(errorData.message || `Tracking API error: ${response.status}`);
    }
    
    return await response.json();
  } catch (error) {
    console.error('Tracking API error:', error);
    throw error;
  }
}

// Utility functions for data transformation
export function formatDateTime(isoDateTime: string): string {
  try {
    const date = new Date(isoDateTime);
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    });
  } catch {
    return isoDateTime;
  }
}

export function formatExpectedDelivery(isoDateTime: string): string {
  try {
    const date = new Date(isoDateTime);
    const now = new Date();
    const isToday = date.toDateString() === now.toDateString();
    const isTomorrow = date.toDateString() === new Date(now.getTime() + 24 * 60 * 60 * 1000).toDateString();
    
    if (isToday) {
      return `Today by ${date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true })}`;
    } else if (isTomorrow) {
      return `Tomorrow by ${date.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true })}`;
    } else {
      return date.toLocaleDateString('en-US', { 
        weekday: 'short',
        month: 'short', 
        day: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        hour12: true
      });
    }
  } catch {
    return isoDateTime;
  }
}

// Simulate cost breakdown from total price for UI display
export function simulateCostBreakdown(totalPrice: number) {
  // Simulate breakdown percentages based on typical shipping costs
  const freight = totalPrice * 0.65; // 65% base freight
  const fuel = totalPrice * 0.15;    // 15% fuel surcharge
  const remoteArea = totalPrice * 0.10; // 10% remote area
  const dimWeight = totalPrice * 0.10;  // 10% dimensional weight adjustment
  
  return {
    baseRate: freight.toFixed(2),
    fuel: fuel.toFixed(2),
    duties: remoteArea.toFixed(2),
    vat: dimWeight.toFixed(2),
    total: totalPrice.toFixed(2)
  };
} 